import { absoluteAppUrl, buildAppHash } from '@/utils/routing.js'
import { withMoveTransition } from '@/utils/viewTransition.js'
import { withRowSlide } from '@/utils/flipSlide.js'
import {
  editorSelection,
  isCollapsedProp,
  focusBlock,
  isEditingProp,
  peekFocusedBlockLocation,
  requestEditorFocus,
  setIsEditing,
  showPropertiesProp,
  type EditorSelectionState,
} from '@/data/properties.js'
import { outlineSurfaceOf, type OutlineSurface } from '@/data/outlineSurface.js'
import { indentDrawnBlock, moveDrawnBlock, outdentDrawnBlock } from '@/data/structuralEditPolicy.js'
import { deleteBlockThroughUi } from '@/utils/deleteBlockThroughUi.js'
import {
  ActionConfig,
  ActionContextType,
  ActionIcon,
  ActionTrigger,
  BlockShortcutDependencies,
  ShortcutBindingDefaults,
} from '@/shortcuts/types.js'
import {
  locationAfterSubtreeRemoval,
  extendSelection,
  selectionBoundaryOf,
  stepInSelectionBoundary,
  type DrawnLocation,
  nextDrawnStep,
  previousDrawnStep,
  surfaceForFocus,
} from '@/utils/selection'

export interface BlockAction {
  id: string
  description: string
  handler: (dependencies: BlockShortcutDependencies, trigger: ActionTrigger) => void | Promise<void>
  defaultBinding?: ShortcutBindingDefaults
  /** Optional glyph for visual surfaces (swipe menus, mobile toolbars,
   *  future command-palette icons). Carried verbatim through
   *  `bindBlockActionContext` onto the resulting `ActionConfig`. */
  icon?: ActionIcon
}

export interface SharedBlockActions {
  indentBlock: BlockAction
  outdentBlock: BlockAction
  moveBlockUp: BlockAction
  moveBlockDown: BlockAction
  deleteBlock: BlockAction
  togglePropertiesDisplay: BlockAction
  toggleBlockCollapse: BlockAction
  extendSelectionUp: BlockAction
  extendSelectionDown: BlockAction
  copyBlock: BlockAction
  copyBlockWithHiddenProperties: BlockAction
  copyBlockRef: BlockAction
  copyBlockEmbed: BlockAction
  copyBlockContent: BlockAction
  copyBlockLink: BlockAction
}

export const bindBlockActionContext = <T extends ActionContextType>(
  context: T,
  action: BlockAction,
  {idPrefix}: { idPrefix?: string } = {},
): ActionConfig<T> => ({
  ...action,
  id: idPrefix ? `${idPrefix}.${action.id}` : action.id,
  context,
  handler: action.handler as ActionConfig<T>['handler'],
})

/** Write to the system clipboard if the platform exposes the async API.
 *  Used by the block-level "copy *" actions; safe to call in non-browser
 *  contexts (jsdom, Node) — the no-clipboard branch silently no-ops so
 *  unit tests can invoke handlers without setting up a clipboard mock. */
const writeToClipboard = (text: string): void => {
  if (typeof navigator === 'undefined' || !navigator.clipboard) return
  void writeTextToClipboard(text)
}

export const requestEditorFocusIfEditing = (uiStateBlock: Block) => {
  if (uiStateBlock.peekProperty(isEditingProp)) {
    requestEditorFocus(uiStateBlock)
  }
}

export const enterEditMode = (uiStateBlock: Block, selection?: EditorSelectionState) => {
  // No-op in read-only workspaces — see setIsEditing for the source-level
  // gate. Bailing here also avoids the side-effects (selection reset, focus
  // request) that would otherwise fire for nothing.
  if (uiStateBlock.repo.isReadOnly) return

  void resetBlockSelection(uiStateBlock)
  // Before the edit flag: the editor places the caret in the commit that
  // mounts it (see focusBlock's `selection`).
  if (selection) void uiStateBlock.set(editorSelection, selection)
  setIsEditing(uiStateBlock, true)
  requestEditorFocus(uiStateBlock)
}

/** First press selects the focused block. Further presses extend through
 *  the drawn order from the focused occurrence, including in panel-level
 *  multi-select mode. A panel's own root cannot start a block range. */
async function extendVerticalSelection(
  step: typeof previousDrawnStep, uiStateBlock: Block, repo: Repo,
  surface: OutlineSurface | null, clearEditing: boolean,
): Promise<boolean> {
  const focused = peekFocusedBlockLocation(uiStateBlock)
  if (!surface || !focused) return false
  const block = repo.block(focused.blockId)
  const here = await surfaceForFocus(block, focused.renderScopeId, surface)
  if (!hasBlockSelection(uiStateBlock)) {
    if (block.id === here.scopeRootId && !(await previousDrawnStep(block, here)).block) return false
    return extendSelection(block.id, uiStateBlock, repo, here, {clearEditing})
  }
  const boundary = await selectionBoundaryOf(block, here.renderScopeId)
  const next = await stepInSelectionBoundary(step, {block, surface: here}, boundary)
  if (!next) return false
  return extendSelection(next.block.id, uiStateBlock, repo, next.surface, {clearEditing})
}

export const extendSelectionDown = (ui: Block, repo: Repo, surface: OutlineSurface | null, clearEditing = false) =>
  extendVerticalSelection(nextDrawnStep, ui, repo, surface, clearEditing)

export const extendSelectionUp = (ui: Block, repo: Repo, surface: OutlineSurface | null, clearEditing = false) =>
  extendVerticalSelection(previousDrawnStep, ui, repo, surface, clearEditing)

export const createSharedBlockActions = ({repo}: { repo: Repo }): SharedBlockActions => {
  // In-place structural shifts deliberately run WITHOUT
  // `withMoveTransition`: the root-level crossfade ghosts the shifting
  // content at both old and new positions (text overlaps itself
  // mid-flight, reading as blur), and the per-block view-transition-name
  // attempt had its own artifacts (see DefaultBlockRenderer). The atomic
  // DOM update from the `NotifyBatch` fix stays the substrate; move
  // up/down now layers `withRowSlide` on top — the per-element setup the
  // old note here wished for: element-level FLIP with plain transform
  // transitions, no snapshot overlay, no duplicated text. Indent/outdent
  // stay instant for now: horizontal reflow changes line wrapping, which
  // translation-only FLIP can't express cleanly.
  const indentBlock: BlockAction = {
    id: 'indent_block',
    description: 'Indent block',
    icon: IndentIncrease,
    handler: async (deps: BlockShortcutDependencies) => {
      await indentDrawnBlock(deps.block, deps)
      requestEditorFocusIfEditing(deps.uiStateBlock)
    },
    defaultBinding: {
      keys: 'Tab',
      eventOptions: {
        preventDefault: true,
      },
    },
  }

  const outdentBlock: BlockAction = {
    id: 'outdent_block',
    description: 'Outdent block',
    icon: IndentDecrease,
    handler: async (deps: BlockShortcutDependencies) => {
      const {block, uiStateBlock, scopeRootId} = deps
      if (!scopeRootId) return
      await outdentDrawnBlock(block, deps)
      requestEditorFocusIfEditing(uiStateBlock)
    },
    defaultBinding: {
      keys: 'Shift+Tab',
      eventOptions: {
        preventDefault: true,
      },
    },
  }
  const moveBlockUp: BlockAction = {
    id: 'move_block_up',
    description: 'Move block up',
    icon: ArrowUp,
    handler: async (deps: BlockShortcutDependencies) => {
      if (!deps.block) return
      await withRowSlide(() => moveDrawnBlock(deps.block, deps, -1))
      requestEditorFocusIfEditing(deps.uiStateBlock)
    },
    defaultBinding: {
      keys: ['$mod+Shift+ArrowUp', '$mod+Shift+k'],
      eventOptions: {
        preventDefault: true,
      },
    },
  }

  const moveBlockDown: BlockAction = {
    id: 'move_block_down',
    description: 'Move block down',
    icon: ArrowDown,
    handler: async (deps: BlockShortcutDependencies) => {
      if (!deps.block) return
      await withRowSlide(() => moveDrawnBlock(deps.block, deps, 1))
      requestEditorFocusIfEditing(deps.uiStateBlock)
    },
    defaultBinding: {
      keys: ['$mod+Shift+ArrowDown', '$mod+Shift+j'],
      eventOptions: {
        preventDefault: true,
      },
    },
  }

  const deleteBlock: BlockAction = {
    id: 'delete_block',
    description: 'Delete block',
    icon: Trash2,
    handler: async (deps: BlockShortcutDependencies) => {
      const {block, uiStateBlock} = deps
      if (!block || !uiStateBlock) return

      // No scope-root special case: deleting the root of a surface is an
      // ordinary delete. Delete REMOVES a subtree, it doesn't relocate one
      // across the surface boundary, so unlike indent / outdent / merge-up it
      // isn't a scope-relative decision at all (see `structuralEditPolicy`).
      // What the surface does afterwards is the surface's problem: a nested
      // backlink/embed re-queries, and a panel showing the deleted page is
      // stepped onto a live destination by the mounted `PanelContentRecovery`
      // watcher. Keeping deletion and navigation decoupled is what makes the
      // hard cases fall out for free — multi-pane duplicates, self-embeds of
      // the focal page, and remote deletes all recover through the one
      // watcher instead of N special cases here.
      //
      // The delete is atomic: a read-only workspace, or a guarded
      // seed-definition ANYWHERE in the subtree, rolls the whole thing back
      // and throws. Since nothing else moved, there is no half-state to clean
      // up and no preflight is needed.

      // `scopeRootId` only locates the post-delete focus target; the delete
      // itself doesn't need it.
      // Don't gate the delete on it, so non-React runners that can't
      // inject a scope (the agent-runtime bridge) still delete — they
      // just skip focus recovery.
      // Removing a subtree shifts its next drawn sibling into its place.
      // At the end of a list prefer the previous sibling, then the owner.
      // Read in `beforeWrite`, so the target is found after the user has
      // answered rather than before — the tree can move while a dialog is
      // open — and while the subtree it skips is still there to skip.
      const focus: {next: DrawnLocation | null} = {next: null}
      const deleted = await deleteBlockThroughUi(block, {
        animate: true,
        beforeWrite: async () => {
          const surface = outlineSurfaceOf(deps)
          focus.next = surface ? await locationAfterSubtreeRemoval(block, surface) : null
        },
      })
      // Don't move focus for a delete a guard refused, or the user cancelled.
      if (deleted && focus.next) void focusBlock(uiStateBlock, focus.next.block.id, {renderScopeId: focus.next.surface.renderScopeId})
    },
    defaultBinding: {
      keys: 'Delete',
    },
  }

  const togglePropertiesDisplay: BlockAction = {
    id: 'toggle_properties',
    description: 'Toggle block properties',
    icon: SlidersHorizontal,
    handler: async (deps: BlockShortcutDependencies) => {
      const {block} = deps
      if (!block) return

      const showProperties = block.peekProperty(showPropertiesProp) ?? false
      await block.set(showPropertiesProp, !showProperties)
    },
    defaultBinding: {keys: 't'},
  }

  const toggleBlockCollapse: BlockAction = {
    id: 'toggle_collapse',
    description: 'Toggle block collapse',
    icon: ChevronsDownUp,
    handler: async (deps: BlockShortcutDependencies) => {
      const {block} = deps
      if (!block) return

      const isCollapsed = block.peekProperty(isCollapsedProp) ?? false
      await withMoveTransition(async () => {
        await block.set(isCollapsedProp, !isCollapsed)
      })
    },
    defaultBinding: {
      keys: 'z',
    },
  }

  /** Serializes the block + its subtree as indented markdown via the
   *  shared `copyBlockToClipboard` helper. The vim-normal-mode plugin
   *  used to define this with the cmd/ctrl+c binding; promoted here so
   *  it's available to any surface (swipe menu, command palette) and
   *  not coupled to the vim plugin. The binding still only fires in
   *  NORMAL_MODE, which only activates when vim is loaded — so removing
   *  vim disables the keybinding without disabling the action. */
  const copyBlock: BlockAction = {
    id: 'copy_block',
    description: 'Copy block to clipboard',
    icon: Copy,
    handler: ({block, propertyDisplay}: BlockShortcutDependencies) => copyBlockToClipboard(block, propertyDisplay),
    defaultBinding: {
      // Vim "yank" family — all copy variants share a `y` prefix:
      // `y y` block, `y r` reference, `y e` embed (see copyBlockRef /
      // copyBlockEmbed below). `y y` mirrors vim's `yy` (yank line).
      // `$mod+c` stays as the platform-native copy.
      keys: ['$mod+c', 'y y'],
      eventOptions: {preventDefault: true},
    },
  }

  /** {@link copyBlock} carrying every property row, including those the outline skips. */
  const copyBlockWithHiddenProperties: BlockAction = {
    id: 'copy_block_with_hidden_properties',
    description: 'Copy block with hidden properties',
    icon: Copy,
    handler: ({block}: BlockShortcutDependencies) => copyBlockToClipboard(block, 'all'),
  }

  const copyBlockRef: BlockAction = {
    id: 'copy_block_ref',
    description: 'Copy block reference',
    icon: Link2,
    handler: ({block}: BlockShortcutDependencies) => {
      writeToClipboard(`((${block.id}))`)
    },
    defaultBinding: {
      // `y r` ("yank reference") is the `y`-prefixed copy-family form;
      // `Alt+y` is kept as the original alternate. Plain-letter sequences
      // match on event.key directly (the logical letter the layout
      // produces), so `y r` is correct on every platform AND layout. The
      // `Alt+y` form relies on `withRecoveredLetterKey` in the reconciler
      // restoring event.key from event.keyCode for alt+letter chords, so it
      // too holds across Mac/Linux/Windows × QWERTY/Colemak/Dvorak.
      keys: ['y r', 'Alt+y'],
    },
  }

  const copyBlockEmbed: BlockAction = {
    id: 'copy_block_embed',
    description: 'Copy block embed',
    icon: ClipboardCopy,
    handler: ({block}: BlockShortcutDependencies) => {
      writeToClipboard(`!((${block.id}))`)
    },
    defaultBinding: {
      // `y e` ("yank embed") is the `y`-prefixed copy-family form;
      // `Shift+y` is kept as the original alternate.
      keys: ['y e', 'Shift+y'],
    },
  }

  const copyBlockContent: BlockAction = {
    id: 'copy_block_content',
    description: 'Copy block text only',
    icon: Text,
    // `y c` ("yank content") — just this block's own text, WITHOUT its
    // subtree. `y y` (copy_block) serializes the whole subtree as
    // indented markdown; this is the single-line counterpart.
    handler: async ({block}: BlockShortcutDependencies) => {
      const data = block.peek() ?? await block.load()
      writeToClipboard(data?.content ?? '')
    },
    defaultBinding: {
      keys: 'y c',
    },
  }

  const copyBlockLink: BlockAction = {
    id: 'copy_block_link',
    description: 'Copy link to block',
    icon: Link,
    // `y l` ("yank link") — an absolute, shareable URL that opens this
    // block: `buildAppHash` for the `#<workspaceId>/<blockId>` hash,
    // `absoluteAppUrl` to promote it to an absolute URL (and drop any
    // agent-runtime pairing secret riding in the current hash). Plain
    // buildAppHash ON PURPOSE — see buildAppHashInContext's docstring for
    // why shared URLs must stay lane-free.
    handler: ({block}: BlockShortcutDependencies) => {
      const workspaceId = repo.activeWorkspaceId
      if (!workspaceId) return
      writeToClipboard(absoluteAppUrl(buildAppHash(workspaceId, block.id)))
    },
    defaultBinding: {
      keys: 'y l',
    },
  }

  const extendSelectionUpAction: BlockAction = {
    id: 'extend_selection_up',
    description: 'Extend selection up',
    handler: async (deps: BlockShortcutDependencies) => {
      await extendSelectionUp(deps.uiStateBlock, repo, outlineSurfaceOf(deps))
    },
    defaultBinding: {
      keys: 'Shift+ArrowUp',
      eventOptions: {
        preventDefault: true,
      },
    },
  }

  const extendSelectionDownAction: BlockAction = {
    id: 'extend_selection_down',
    description: 'Extend selection down',
    handler: async (deps: BlockShortcutDependencies) => {
      await extendSelectionDown(deps.uiStateBlock, repo, outlineSurfaceOf(deps))
    },
    defaultBinding: {
      keys: 'Shift+ArrowDown',
      eventOptions: {
        preventDefault: true,
      },
    },
  }

  return {
    indentBlock,
    outdentBlock,
    moveBlockUp,
    moveBlockDown,
    deleteBlock,
    togglePropertiesDisplay,
    toggleBlockCollapse,
    extendSelectionUp: extendSelectionUpAction,
    extendSelectionDown: extendSelectionDownAction,
    copyBlock,
    copyBlockWithHiddenProperties,
    copyBlockRef,
    copyBlockEmbed,
    copyBlockContent,
    copyBlockLink,
  }
}
